// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> missingRolls(vector<int>& rolls, int mean, int n) {
        static const int MAX_V = 6;
        static const int MIN_V = 1;

        const int total = accumulate(cbegin(rolls), cend(rolls), 0);
        const int missing = mean * (n + size(rolls)) - total;
        if (missing < MIN_V * n || missing > MAX_V * n) {
            return {};
        }
        const int q = missing / n;
        const int r = missing % n;
        vector<int> result(n);
        for (int i = 0; i < size(result); ++i) {
            result[i] = q + int(i < r);
        }
        return result;
    }
};


// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    vector<int> missingRolls(vector<int>& rolls, int mean, int n) {
        static const int MAX_V = 6;
        static const int MIN_V = 1;

        const int total = accumulate(cbegin(rolls), cend(rolls), 0);
        const int missing = mean * (n + size(rolls)) - total;
        if (missing < MIN_V * n || missing > MAX_V * n) {
            return {};
        }
        const int q = (missing - MIN_V * n) / (MAX_V - MIN_V);
        const int r = (missing - MIN_V * n) % (MAX_V - MIN_V);
        vector<int> result(n);
        for (int i = 0; i < size(result); ++i) {
            result[i] = (i < q) ? MAX_V : ((i == q) ? MIN_V + r : MIN_V);
        }
        return result;
    }
};

kamyu-c-find-mode-in-binary-search-tree-:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<int> findMode(TreeNode* root) {
        if (!root) {
            return {};
        }

        vector<int> result;
        TreeNode *prev = nullptr;
        int cnt = 1, max_cnt = 0;
        inorder(root, &prev, &cnt, &max_cnt, &result);
        return result;
    }

private:    
    void inorder(TreeNode *root, TreeNode **prev, int *cnt, int *max_cnt, vector<int> *result) {
        if (root == nullptr) {
            return;
        }

        inorder(root->left, prev, cnt, max_cnt, result);
        if (*prev) {
            if (root->val == (*prev)->val) {
                ++(*cnt);
            } else {
                *cnt = 1;
            }
        }
        if (*cnt > *max_cnt) {
            *max_cnt = *cnt;
            result->clear();
            result->emplace_back(root->val);
        } else if (*cnt == *max_cnt) {
            result->emplace_back(root->val);
        }
        *prev = root;
        inorder(root->right, prev, cnt, max_cnt, result);
    }
};

kamyu-c-find-most-frequent-vowel-and-con:
// Time:  O(n + 26)
// Space: O(26)

// freq table
class Solution {
public:
    int maxFreqSum(string s) {
        unordered_set<char> VOWELS = {'a', 'e', 'i', 'o', 'u'};
        vector<int> cnt(26);
        for (const auto& x : s) {
            ++cnt[x - 'a'];
        }
        int mx1 = 0, mx2 = 0;
        for (int i = 0; i < size(cnt); ++i) {
            if (VOWELS.count(i + 'a')) {
                mx1 = max(mx1, cnt[i]);
            } else {
                mx2 = max(mx2, cnt[i]);
            }
        }
        return mx1 + mx2;
    }
};

