// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int nearestValidPoint(int x, int y, vector<vector<int>>& points) {
        int smallest = numeric_limits<int>::max();
        int idx = -1;
        for (int i = 0; i < size(points); ++i) {
            int dx = x - points[i][0], dy = y - points[i][1];
            if (dx * dy == 0 && abs(dx) + abs(dy) < smallest) {
                smallest = abs(dx) + abs(dy);
                idx = i;
            }
        }
        return idx;
    }
};

kamyu-c-find-nearest-right-node-in-binar:
// Time:  O(n)
// Space: O(w)

class Solution {
public:
    TreeNode* findNeartestRightNode(TreeNode* root, TreeNode* u) {
        vector<TreeNode *> q = {root};
        while (!empty(q)) {
            vector<TreeNode *> new_q;
            for (int i = 0; i < size(q); ++i) {
                if (q[i] == u) {
                    return i + 1 < size(q) ? q[i + 1] : nullptr;
                }
                if (q[i]->left) {
                    new_q.emplace_back(q[i]->left);
                }
                if (q[i]->right) {
                    new_q.emplace_back(q[i]->right);
                }
            }
            q = move(new_q);
        }
        return nullptr;
    }
};

kamyu-c-find-nth-smallest-integer-with-k:
// Time:  ctor:    O(r^2)
//        runtime: O(r)
// Space: O(r^2)

// dp, combinatorics
const auto& init = [](int k) {
    vector<vector<int64_t>> dp(k + 1, vector<int64_t>(k + 1));
    for (int i = 0; i < size(dp); ++i) {
        dp[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
        }
    }
    return dp;
};

static const int MAX_K = 50;
const auto& DP = init(MAX_K);
class Solution {
public:
    long long nthSmallest(long long n, int k) {
        int64_t result = 0;
        for (int i = MAX_K - 1; i >= 0; --i) {
            if (n <= DP[i][k]) {
                continue;
            }
            n -= DP[i][k];
            result |= 1ll << i;
            if (--k == 0) {
                break;
            }
        }
        return result;
    }
};

kamyu-c-find-number-of-coins-to-place-in:
// Time:  O(n)
// Space: O(n)

// iterative dfs
class Solution {
public:
    vector<long long> placedCoins(vector<vector<int>>& edges, vector<int>& cost) {
        vector<vector<int>> adj(size(cost));
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        vector<long long> result(size(cost));
        const auto& iter_dfs = [&]() {
            vector<long long> result(size(cost));
            using RET = vector<int64_t>;
            RET ret = {cost[0]};
            vector<tuple<int, int, int, int, shared_ptr<RET>, RET *>> stk = {{1, 0, -1, -1, nullptr, &ret}};
            while (!stk.empty()) {
                const auto [step, u, p, i, new_ret, ret] = stk.back(); stk.pop_back();
                if (step == 1) {
                    stk.emplace_back(4, u, -1, -1, nullptr, ret);
                    stk.emplace_back(2, u, p, 0, nullptr, ret);
                } else if (step == 2) {
                    if (i == size(adj[u])) {
                        continue;
                    }
                    const auto& v = adj[u][i];
                    stk.emplace_back(2, u, p, i + 1, new_ret, ret);
                    if (v == p) {
                        continue;
                    }
                    const auto& new_ret = make_shared<RET>(RET{cost[v]});
                    stk.emplace_back(3, -1, -1, -1, new_ret, ret);
                    stk.emplace_back(1, v, u, -1, nullptr, new_ret.get());
                } else if (step == 3) {
                    for (const auto& c : *new_ret) {
                        ret->emplace_back(c);
                    }
                    sort(begin(*ret), end(*ret));
                    if (size(*ret) > 5) {
                        ret->assign({(*ret)[0], (*ret)[1], (*ret)[size(*ret) - 3], (*ret)[size(*ret) - 2], (*ret)[size(*ret) - 1]});
                    }
                } else if (step == 4) {
                    result[u] = size(*ret) < 3 ? 1 : max({(*ret)[0] * (*ret)[1] * (*ret)[size(*ret) - 1], (*ret)[size(*ret) - 3] * (*ret)[size(*ret) - 2] * (*ret)[size(*ret) - 1], static_cast<int64_t>(0)});
                }
            }
            return result;
        };

        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(n)
// dfs
class Solution2 {
public:
    vector<long long> placedCoins(vector<vector<int>>& edges, vector<int>& cost) {
        vector<vector<int>> adj(size(cost));
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        vector<long long> result(size(cost));
        const function<vector<int64_t> (int, int)> dfs = [&](int u, int p) {
            vector<int64_t> arr = {cost[u]};
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                for (const auto& c : dfs(v, u)) {
                    arr.emplace_back(c);
                }
                sort(begin(arr), end(arr));
                if (size(arr) > 5) {
                    arr = {arr[0], arr[1], arr[size(arr) - 3], arr[size(arr) - 2], arr[size(arr) - 1]};
                }
            }
            result[u] = size(arr) < 3 ? 1 : max({arr[0] * arr[1] * arr[size(arr) - 1], arr[size(arr) - 3] * arr[size(arr) - 2] * arr[size(arr) - 1], static_cast<int64_t>(0)});
            return arr;
        };

        dfs(0, -1);
        return result;
    }
};

kamyu-c-find-number-of-ways-to-reach-the:
// Time:  O(logk)
// Space: O(logk)

// combinatorics
class Solution {
public:
    int waysToReachStair(int k) {
        const auto& bit_length = [](int x) {
            return (x ? std::__lg(x) : -1) + 1;
        };

        const auto& ceil_log2_x = [&](int x) {
            return bit_length(x - 1);
        };

        int l = ceil_log2_x(k);
        for (; (1ll << l) - k <= l + 1; ++l);
        vector<__int128> fact(l + 1, 1);
        for (int i = 0; i + 1 < size(fact); ++i) {
            fact[i + 1] = fact[i] * (i + 1);
        }
        const auto& nCr = [&](int n, int r) {
            if (!(0 <= r && r <= n)) {
                return static_cast<__int128>(0);
            }
            return fact[n] / fact[r] / fact[n - r];
        };

        int result = 0;
        for (int i = 0; i < l; ++i) {
            result += nCr(i + 1, (1 << i) - k);
        }
        return result;
    }
};

