kamyu-c-find-occurrences-of-an-element-i:
// Time:  O(n + q)
// Space: O(n)

// array
class Solution {
public:
    vector<int> occurrencesOfElement(vector<int>& nums, vector<int>& queries, int x) {
        vector<int> lookup;
        for (int i = 0; i < size(nums); ++i) {
            if (nums[i] != x) {
                continue;
            }
            lookup.emplace_back(i);
        }
        vector<int> result(size(queries));
        for (int i = 0; i < size(queries); ++i) {
            result[i] = queries[i] - 1 < size(lookup) ? lookup[queries[i] - 1] : -1;
        }
        return result;
    }
};

kamyu-c-find-original-array-from-doubled:
// Time:  O(n + klogk), k is the distinct number of changed
// Space: O(k)

class Solution {
public:
    vector<int> findOriginalArray(vector<int>& changed) {
        if (size(changed) % 2) {
            return {};
        }
        unordered_map<int, int> cnts;
        for (const auto& x : changed) {
            ++cnts[x];
        }
        vector<int> nums;
        for (const auto& [x, _] : cnts) {
            nums.emplace_back(x);
        }
        sort(begin(nums), end(nums));
        vector<int> result;
        for (const auto& x : nums) {
            if (cnts[x] > cnts[2 * x]) {
                return {};
            }
            for (int i = 0; i < cnts[x]; ++i, --cnts[2 * x]) {
                result.emplace_back(x);
            }
        }
        return result;
    }
};

