// Space: O(l)

class Solution {
public:
    string nearestPalindromic(string n) {
        const auto l = n.size();
        unordered_set<long long> candidates;
        candidates.emplace(static_cast<long long>(pow(10, l)) + 1);
        candidates.emplace(static_cast<long long>(pow(10, l - 1)) - 1);
        auto prefix = stol(n.substr(0, (l + 1) / 2));
        for (long long i = -1; i <= 1; ++i) {
            auto p = to_string(prefix + i);
            auto pp = p + string(p.rbegin() + (l % 2), p.rend());
            candidates.emplace(stol(pp));
        }
        long long num = stol(n), closest_val = numeric_limits<long long>::max();
        candidates.erase(num);
        for (const auto& val : candidates) {
            if (abs(val - num) < abs(closest_val - num)) {
                closest_val = val;
            } else if (abs(val - num) == abs(closest_val - num)) {
                closest_val = min(closest_val, val);
            }
        }
        return to_string(closest_val);
    }
};

kamyu-c-find-the-count-of-good-integers-:
// Time:  O(n + 10 * 10^((n + 1)/2))
// Space: O(n + 10 * (10 * nHr(10, n/2)))

// combinatorics, freq table
class Solution {
private:
    template<typename T>
    struct VectorHash {
        size_t operator()(const std::vector<T>& v) const {
            size_t seed = 0;
            for (const auto& i : v) {
                seed ^= std::hash<T>{}(i) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            }
            return seed;
        }
    };

public:
    long long countGoodIntegers(int n, int k) {
        const auto& reverse = [](int x, int n) {
            if (n % 2) {
                x /= 10;
            }
            int result = 0;
            for (; x; x /= 10) {
                result = result * 10 + x % 10;
            }
            return result;
        };

        const auto& palindrome = [&](int64_t x, int n) {
            return x * pow(10, n / 2) + reverse(x, n);
        };

        const auto& count = [](auto x) {
            vector<int> cnt(10);
            for (; x; x /= 10) {
                ++cnt[x % 10];
            }
            return cnt;
        };

        vector<int> fact(n + 1, 1);
        for (int i = 0; i + 1 < size(fact); ++i) {
            fact[i + 1] = fact[i] * (i + 1);
        }
        const int l = (n + 1) / 2;
        int64_t result = 0;
        unordered_set<vector<int>, VectorHash<int>> lookup;
        const int upper_bound = pow(10, l);
        for (int d = pow(10, l - 1); d < upper_bound; ++d) {
            const int64_t x = palindrome(d, n);
            if (x % k) {
                continue;
            }
            const auto& cnt = count(x);
            if (lookup.count(cnt)) {
                continue;
            }
            lookup.emplace(cnt);
            int64_t total = (n - cnt[0]) * fact[n - 1];
            for (const auto& c : cnt) {
                total /= fact[c];
            }
            result += total;
        }
        return result;
    }
};

