        int result = 0, i = 0;
        for (int j = 0; i < arr1.size() && j < arr2.size();) {
            if (arr1[i] - arr2[j] > d) {
                ++j;
                continue;
            }
            result += arr2[j] - arr1[i] > d;
            ++i;
        }
        return result + arr1.size() - i;
    }
};

