        for (int i = 0; i < 3; ++i) {
            const int d = mx - nums1[i];
            unordered_map<int, int> cnt1;
            for (const auto& x : nums1) {
                ++cnt1[x + d];
            }
            if (check(cnt2, cnt1)) {
                return d;
            }
        }
