        const int base = pow(10, k - 1);
        for (int i = 0, curr = 0; i < size(s); ++i) {
            if (i - k >= 0) {
                curr -= (s[i - k] - '0') * base;
            }
            curr = curr * 10 + (s[i] - '0');
