        unordered_map<int, pair<int, int>> lookup;
        for (int i = 0; i < size(mat); ++i) {
            for (int j = 0; j < size(mat[0]); ++j) {
                lookup[mat[i][j]] = {i, j};
            }
        }
        vector<int> row(size(mat)), col(size(mat[0]));
