//        add:          O(1)
//        deleteOne:    O(1)
//        hasFrequency: O(1)
// Space: O(min(n, r))

// freq table
class FrequencyTracker {
public:
    FrequencyTracker() {

    }

    void add(int number) {
        if (--freq_[cnt_[number]] == 0) {
            freq_.erase(cnt_[number]);
        };
        ++freq_[++cnt_[number]];
    }

    void deleteOne(int number) {
        if (!cnt_.count(number)) {
            return;
        }
        if (--freq_[cnt_[number]] == 0) {
            freq_.erase(cnt_[number]);
        }
        ++freq_[--cnt_[number]];
        if (cnt_[number] == 0) {
            cnt_.erase(number);
        }
    }

    bool hasFrequency(int frequency) {
        return freq_.count(frequency);
    }

private:
    unordered_map<int, int> cnt_;
    unordered_map<int, int> freq_;
};

kamyu-c-friend-circles-0kx66vy:
// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int findCircleNum(vector<vector<int>>& M) {
        UnionFind circles(M.size());
        for (int i = 0; i < M.size(); ++i) {
            for (int j = 0; j < M[i].size(); ++j) {
                if (M[i][j] && i != j) {
                    circles.union_set(i, j);
                }
            }
        }
        return circles.size();
    }

private:
    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), count_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            void union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root != y_root) {
                    set_[min(x_root, y_root)] = max(x_root, y_root);
                    --count_;
                }
            }

            int size() const {
                return count_;
            }

        private:
            vector<int> set_;
            int count_;
    };
};

