kamyu-c-good-subsequence-queries-0a30slo:
// Time:  precompute: O(rlog(logr))
//        runtime:    O(r + (n + q) * log(logr))
// Space: O(rlog(logr) + n)

// number theory, freq table
const auto& precompute = [](int r) {
    vector<vector<int>> factors(r + 1);
    int curr = 1, k = 0;
    for (int i = 2; i < size(factors); i++) {
        if (!empty(factors[i])) {
            continue;
        }
        if (curr * i <= r) {
            curr *= i;
            ++k;
        }
        for (int j = i; j < size(factors); j += i) {
            factors[j].emplace_back(i);
        }
    }
    return pair(factors, k);
};

const int MAX_NUMS = 50000;
const auto& [FACTORS, K] = precompute(MAX_NUMS);
class Solution {
public:
    int countGoodSubseq(vector<int>& nums, int p, vector<vector<int>>& queries) {
        if (size(nums) == 1) {
            return 0;
        }
        int curr = 0;
        int mx = ranges::max(nums);
        for (const auto& q : queries) {
            mx = max(mx, q[1]);
        }
        vector<int> cnt(mx + 1), cnt2(size(nums) + 1);
        const auto& update = [&](int x, int d) {
            if (x % p) {
                return;
            }
            for (const auto& q : FACTORS[x / p]) {
                --cnt2[cnt[q]];
                cnt[q] += d;
                ++cnt2[cnt[q]];
            }
            curr += d;
        };

        const auto& check = [&]() {
            if (curr == 0 || cnt2[curr]) {
                return false;
            }
            if (curr != size(nums) || size(nums) > K) {
                return true;
            }
            for (int i = 0; i < size(nums); ++i) {
                update(nums[i], -1);
                const auto& found = (cnt2[curr] == 0);
                update(nums[i], +1);
                if (found) {
                    return true;
                }
            }
            return false;
        };

        int result = 0;
        for (const auto& x : nums) {
            update(x, +1);
        }
        for (const auto& q : queries) {
            const auto& i = q[0], &x = q[1];
            update(nums[i], -1);
            nums[i] = x;
            update(nums[i], +1);
            if (check()) {
                ++result;
            }
        }
        return result;
    }
};

kamyu-c-graph-connectivity-with-threshol:
// Time:  O((nlogn + q) * α(n)) ~= O(nlogn + q)
// Space: O(n)

class Solution {
public:
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        UnionFind union_find(n);
        for (int i = threshold + 1; i <= n; ++i) {
            // https://stackoverflow.com/questions/25905118/finding-big-o-of-the-harmonic-series
            // sum of harmonic series is O(logn)
            for (int j = 2 * i; j <= n; j += i) {
                union_find.union_set(i - 1, j - 1);
            }
        }
        vector<bool> result;
        for (const auto& q : queries) {
            result.emplace_back(union_find.find_set(q[0] - 1) == union_find.find_set(q[1] - 1));
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), rank_(n), count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            if (rank_[x_root] < rank_[y_root]) {  // Union by rank.
                set_[x_root] = y_root;
            } else if (rank_[x_root] > rank_[y_root]) {
                set_[y_root] = x_root;
            } else {
                set_[y_root] = x_root;
                ++rank_[x_root];
            }
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        int count_;
    };
};

kamyu-c-graph-valid-tree-1ploh4s:
// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)

// Same complexity, but faster version.
class Solution {
public:
    bool validTree(int n, vector<pair<int, int>>& edges) {
        if (edges.size() != n - 1) {
            return false;
        }

        unordered_map<int, vector<int>> neighbors;
        for (const auto& edge : edges) {
            neighbors[edge.first].emplace_back(edge.second);
            neighbors[edge.second].emplace_back(edge.first);
        }

        queue<int> q;
        q.emplace(0);
        unordered_set<int> visited;
        visited.emplace(0);
        while (!q.empty()) {
            const int i = q.front();
            q.pop();
            for (const auto& node : neighbors[i]) {
                if (!visited.count(node)) {
                    visited.emplace(node);
                    q.emplace(node);
                }
            }
        }
        return visited.size() == n;
    }
};

// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)
class Solution2 {
public:
    struct node {
        int parent = -1;
        vector<int>neighbors;
    };

    bool validTree(int n, vector<pair<int, int>>& edges) {
        unordered_map<int, node> nodes;
        for (const auto& edge : edges) {
            nodes[edge.first].neighbors.emplace_back(edge.second);
            nodes[edge.second].neighbors.emplace_back(edge.first);
        }

        queue<int> q;
        q.emplace(0);
        unordered_set<int> visited;
        visited.emplace(0);
        while (!q.empty()) {
            const int i = q.front();
            q.pop();
            for (const auto& node : nodes[i].neighbors) {
                if (node != nodes[i].parent) {
                    if (visited.find(node) != visited.end()) {
                        return false;
                    } else {
                        visited.emplace(node);
                        nodes[node].parent = i;
                        q.emplace(node);
                    }
                }
            }
        }
        return visited.size() == n;
    }
};

