        vector<TreeNode *> q = {root};
        while (!empty(q)) {
            vector<TreeNode *> new_q;
            for (const auto& u : q) {
                if (u->left && u->left->right != u) {
                    new_q.emplace_back(u->left);
                }
                if (u->right && u->right->left != u) {
                    new_q.emplace_back(u->right);
                }
            }
            q = move(new_q);
            ++result;
        }
        return result;
    }
};

