            dp[i % 2] = (i - 1 >= 0 && colors[i - 1] == colors[i]) ? max(dp[((i - 2) % 2 + 2) % 2] + nums[i], dp[((i - 1) % 2 + 2) % 2]) : dp[((i - 1) % 2 + 2) % 2] + nums[i];
        }
