class Solution {
public:
    vector<int> intersection(vector<vector<int>>& nums) {
        static const int MAX_NUM = 1000;
        vector<int> cnt(MAX_NUM + 1);
        for (const auto& num : nums) {
            for (const auto& x : num) {
